class Solution:
    def maximumAmount(self, coins):
        from collections import deque

        m, n = len(coins), len(coins[0])
        # dp[i][j][k]: max coins at (i,j) with k neutralizations used
        dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
        dp[0][0][0] = coins[0][0]
        if coins[0][0] < 0:
            dp[0][0][1] = 0  # use neutralization at start

        for i in range(m):
            for j in range(n):
                for k in range(3):
                    if dp[i][j][k] == -float('inf'):
                        continue
                    # Move down
                    if i + 1 < m:
                        val = coins[i + 1][j]
                        # Without neutralization
                        dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k] + val)
                        # With neutralization
                        if k < 2:
                            dp[i + 1][j][k + 1] = max(dp[i + 1][j][k + 1], dp[i][j][k])
                    # Move right
                    if j + 1 < n:
                        val = coins[i][j + 1]
                        # Without neutralization
                        dp[i][j + 1][k] = max(dp[i][j + 1][k], dp[i][j][k] + val)
                        # With neutralization
                        if k < 2:
                            dp[i][j + 1][k + 1] = max(dp[i][j + 1][k + 1], dp[i][j][k])

        return max(dp[m - 1][n - 1])

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        count = 0
        total_sum = sum(nums)
        left_sum = 0
        for i in range(len(nums) - 1):
            left_sum += nums[i]
            right_sum = total_sum - left_sum
            if (left_sum - right_sum) % 2 == 0:
                count += 1
        return count

