class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        skip = False  # Flag to determine whether to skip the current cell

        for i in range(rows):
            if i % 2 == 0:
                # Traverse right
                for j in range(cols):
                    if not skip:
                        result.append(grid[i][j])
                    skip = not skip
            else:
                # Traverse left
                for j in range(cols - 1, -1, -1):
                    if not skip:
                        result.append(grid[i][j])
                    skip = not skip
        return result

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n:
            return False
        for i in range(n - k + 1):
            substring = s[i:i+k]
            # Check if all characters in the substring are the same
            if all(c == substring[0] for c in substring):
                # Check the character before the substring
                if i > 0 and s[i-1] == substring[0]:
                    continue
                # Check the character after the substring
                if i + k < n and s[i+k] == substring[0]:
                    continue
                return True
        return False

