class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        from collections import defaultdict

        # Count the frequency of each number in nums
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1

        # If k is already in nums, start with its current frequency
        max_freq = freq.get(k, 0)

        # Try adding x to each subarray and see how it affects the frequency of k
        for i in range(len(nums)):
            for j in range(i, len(nums)):
                # Calculate the sum of the subarray
                subarray_sum = sum(nums[i:j+1])

                # Calculate the value of x that would make the sum of the subarray equal to k
                x = k - subarray_sum

                # Add x to each element in the subarray
                for l in range(i, j+1):
                    nums[l] += x

                # Count the frequency of k in the updated array
                freq_k = freq.get(k, 0)
                for num in nums:
                    if num == k:
                        freq_k += 1

                # Update the maximum frequency of k
                max_freq = max(max_freq, freq_k)

                # Reset the array to its original state
                for l in range(i, j+1):
                    nums[l] -= x

        return max_freq

