class Solution:
    def separateSquares(self, squares):
        # Collect all unique y-coordinates: bottom and top of each square
        ys = []
        for x, y, l in squares:
            ys.append(y)
            ys.append(y + l)
        ys = sorted(set(ys))

        # Function to compute the total area above a given y-coordinate
        def area_above(y_line):
            total = 0.0
            for x, y, l in squares:
                if y_line < y:
                    # Entire square is above the line
                    total += l * l
                elif y_line < y + l:
                    # Partial overlap
                    total += (y + l - y_line) * l
                # else: square is completely below the line
            return total

        # Function to compute the total area below a given y-coordinate
        def area_below(y_line):
            total = 0.0
            for x, y, l in squares:
                if y_line > y + l:
                    # Entire square is below the line
                    total += l * l
                elif y_line > y:
                    # Partial overlap
                    total += (y_line - y) * l
                # else: square is completely above the line
            return total

        # Binary search for the y-coordinate where area above equals area below
        low = min(ys)
        high = max(ys)
        for _ in range(100):
            mid = (low + high) / 2
            above = area_above(mid)
            below = area_below(mid)
            if above > below:
                low = mid
            else:
                high = mid

        return (low + high) / 2

