class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        from functools import lru_cache

        n = len(nums)

        @lru_cache(None)
        def dp(i, cur_sum, parity):
            # i: current index in nums
            # cur_sum: current alternating sum
            # parity: 0 if next element is at even index in subsequence, 1 if odd
            if i == n:
                if cur_sum == k:
                    return 1  # product of empty subsequence is 1
                else:
                    return None  # invalid

            # Option 1: skip nums[i]
            res1 = dp(i + 1, cur_sum, parity)

            # Option 2: take nums[i]
            if parity == 0:
                new_sum = cur_sum + nums[i]
            else:
                new_sum = cur_sum - nums[i]
            res2 = dp(i + 1, new_sum, 1 - parity)
            if res2 is not None:
                res2 = res2 * nums[i]

            # Choose the better result
            if res1 is None and res2 is None:
                return None
            if res1 is None:
                return res2
            if res2 is None:
                return res1
            return max(res1, res2)

        result = dp(0, 0, 0)
        if result is None or result > limit:
            return -1
        return result

