class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Helper function to compute Manhattan distance
        def manhattan(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        # Precompute all pairwise distances
        n = len(points)
        dist = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(i+1, n):
                d = manhattan(points[i], points[j])
                dist[i][j] = d
                dist[j][i] = d

        # Binary search over possible minimum distances
        lo, hi = 0, 2*side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            # Check if there is a subset of size k with minimum distance >= mid
            # Use a simple backtracking with pruning
            def backtrack(start, selected):
                if len(selected) == k:
                    return True
                for i in range(start, n):
                    # Prune if not enough points left
                    if n - i < k - len(selected):
                        break
                    # Check if this point is compatible with the selected ones
                    ok = True
                    for j in selected:
                        if dist[i][j] < mid:
                            ok = False
                            break
                    if ok:
                        if backtrack(i+1, selected + [i]):
                            return True
                return False

            if backtrack(0, []):
                lo = mid
            else:
                hi = mid - 1
        return lo

