                for c in dp[i + 1][j - 1]:
                    if c + 1 <= k:
                        dp[i][j][c + 1] = dp[i + 1][j - 1][c] + 2
                # We can also skip the character at i or j
                for c in dp[i + 1][j]:
                    dp[i][j][c] = max(dp[i][j].get(c, 0), dp[i + 1][j][c])
                for c in dp[i][j - 1]:
                    dp[i][j][c] = max(dp[i][j].get(c, 0), dp[i][j - 1][c])

        # The answer is the maximum length of the palindrome subsequence with at most k operations
        return max(dp[0][n - 1].get(c, 0) for c in dp[0][n - 1] if c <= k)

