class Solution:
    def minTime(self, skill, mana):
        n = len(skill)
        m = len(mana)
        # dp[i][j]: minimum time to finish first j potions with first i wizards
        # We can optimize space to 1D DP
        dp = [0] * (m + 1)
        for i in range(1, n + 1):
            new_dp = [0] * (m + 1)
            for j in range(1, m + 1):
                if i == 1:
                    # Only one wizard, just accumulate
                    new_dp[j] = new_dp[j - 1] + skill[i - 1] * mana[j - 1]
                else:
                    # Take the max of previous wizard's finish time and current wizard's finish time
                    new_dp[j] = max(new_dp[j - 1], dp[j]) + skill[i - 1] * mana[j - 1]
            dp = new_dp
        return dp[m]

