class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Iterate over possible k from 0 to len(queries)
        for k in range(len(queries) + 1):
            # Initialize the current array as a copy of nums
            cur = nums[:]
            # Apply the first k queries
            for i in range(k):
                l, r, val = queries[i]
                # Decrement each element in the range [l, r] by val
                for idx in range(l, r + 1):
                    cur[idx] -= val
            # Check if the current array is a Zero Array
            if all(x == 0 for x in cur):
                return k
        # If no Zero Array is found, return -1
        return -1

class Solution:
