class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # Helper function to check if a number is beautiful
        def is_beautiful(n: int) -> bool:
            digits = [int(d) for d in str(n)]
            digit_sum = sum(digits)
            digit_product = 1
            for d in digits:
                digit_product *= d
            # Avoid division by zero, though digit_sum will never be zero for positive integers
            return digit_product % digit_sum == 0

        # Count beautiful numbers in the range [l, r]
        count = 0
        for num in range(l, r + 1):
            if is_beautiful(num):
                count += 1
        return count

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        # Count the initial number of active sections
        initial_active = s.count('1')

        # If the string is all '1's or all '0's, no trade can improve the count
        if initial_active == n or initial_active == 0:
            return initial_active

        # Compute the maximum possible active sections after one trade
        # The trade can at most convert a block of '0's surrounded by '1's to '1's
        # The maximum increase is the length of the largest block of '0's surrounded by '1's
        max_increase = 0
        i = 0
        while i < n:
            if s[i] == '0':
                # Find the length of the block of '0's
                j = i
                while j < n and s[j] == '0':
                    j += 1
                # Check if the block is surrounded by '1's
                if i > 0 and j < n and s[i - 1] == '1' and s[j] == '1':
                    max_increase = max(max_increase, j - i)
                i = j
            else:
                i += 1

        return initial_active + max_increase

