class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Preprocess each properties[i] into a set for faster intersection
        sets = [set(prop) for prop in properties]

        # Build adjacency list
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                # Compute intersection
                if len(sets[i].intersection(sets[j])) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # BFS to count connected components
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                # BFS
                queue = [i]
                visited[i] = True
                while queue:
                    node = queue.pop(0)
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components

class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for i, ch in enumerate(s, 1):
            reversed_index = ord('z') - ord(ch) + 1
            total += reversed_index * i
        return total

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # The total number of cells on the deck
        total_cells = n * n
        # The maximum number of containers that can be loaded without exceeding maxWeight
        max_containers = maxWeight // w
        # The result is the minimum of total_cells and max_containers
        return min(total_cells, max_containers)

