def count_snake_numbers(L, R):
    # Count snake numbers up to N
    def count_up_to(N):
        if N < 10:
            return 0
        s = str(N)
        length = len(s)
        # Count snake numbers with fewer digits than length
        count = 0
        for l in range(2, length):
            # For each length l, count snake numbers
            # The top digit can be from 1 to 9
            # The other digits can be from 0 to top digit - 1
            # So for each top digit, there are (top digit)^(l - 1) numbers
            for top_digit in range(1, 10):
                count += top_digit ** (l - 1)
        # Now count snake numbers with the same length as N
        # Use a recursive function
        def count_recursive(pos, top_digit, tight):
            if pos == length:
                return 1
            limit = int(s[pos]) if tight else 9
            total = 0
            for digit in range(0, limit + 1):
                if pos == 0:
                    # The top digit
                    total += count_recursive(pos + 1, digit, tight and digit == limit)
                else:
                    if digit < top_digit:
                        total += count_recursive(pos + 1, top_digit, tight and digit == limit)
            return total
        count += count_recursive(0, 0, True)
        return count

    return count_up_to(R) - count_up_to(L - 1)

