    # Merge bad intervals just in case (though they are given non-overlapping and sorted)
    # We'll use a greedy approach: from current position, try to jump as far as possible within [A, B]
    # while avoiding bad squares. Since N can be huge, we need an efficient approach.
    # We'll use DP with memoization for positions up to some limit, and for larger positions, we use greedy.
    # Actually, since B is at most 20, we can use DP for positions up to N limited by bad intervals.
    # We'll use a set for bad squares.
    bad_set = set()
    for L, R in bad_intervals:
        for x in range(L, R + 1):
            bad_set.add(x)
    # DP with memoization
    from functools import lru_cache
    @lru_cache(None)
    def can_reach(x):
        if x == N:
            return True
        for i in range(A, B + 1):
            nxt = x + i
            if nxt > N:
                continue
            if nxt in bad_set:
                continue
            if can_reach(nxt):
                return True
        return False
    if can_reach(1):
