import sys
import bisect

def generate_400_numbers(limit):
    # Generate all primes up to sqrt(limit)
    max_prime = int(limit**0.5) + 1
    sieve = [True] * (max_prime + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(max_prime**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, max_prime + 1, i):
                sieve[j] = False
    primes = [i for i, is_prime in enumerate(sieve) if is_prime]

    numbers = set()
    # For each pair of distinct primes, generate numbers with even exponents
    for i in range(len(primes)):
        p = primes[i]
        p_pow = p * p
        while p_pow <= limit:
            for j in range(i+1, len(primes)):
                q = primes[j]
                q_pow = q * q
                while p_pow * q_pow <= limit:
                    numbers.add(p_pow * q_pow)
                    q_pow *= q
            p_pow *= p
    return sorted(numbers)

def main():
